# Check what failure modes are most common and not covered by existing skills
# Existing skills cover: obstacle-pivot (FM-2.2), state-check-before-action (FM-1.1, FM-2.6), 
# grep-first-reading, classify-then-act, verification (FM-3.3), tool-discipline (FM-2.1),
# file-safety (FM-2.3), error-handling (FM-2.4), handoff, task-adherence (FM-2.4, FM-5.3)
# 
# Look for uncovered FM codes
python3 << 'EOF'
import json, os

# Read recent evaluations to find FM code frequency
eval_dir = ".state/evaluations/"
fm_counts = {}
if os.path.exists(eval_dir):
    for f in os.listdir(eval_dir):
        if f.endswith('.json'):
            try:
                data = json.load(open(os.path.join(eval_dir, f)))
                issues = data.get('issues', [])
                for issue in issues:
                    code = issue.get('code', 'unknown')
                    fm_counts[code] = fm_counts.get(code, 0) + 1
            except:
                pass

print("FM code frequency (from evaluations):")
for code, count in sorted(fm_counts.items(), key=lambda x: -x[1]):
    print(f"  {code}: {count}")
EOF

# Check evaluations directory structure
ls .state/evaluations/ 2>/dev/null | head -5
# Also check ERROR_LOG
head -5 .state/ERROR_LOG.jsonl 2>/dev/null
wc -l .state/ERROR_LOG.jsonl 2>/dev/null
# Get FM code counts from error log
python3 << 'EOF'
import json

counts = {}
try:
    with open(".state/ERROR_LOG.jsonl") as f:
        for line in f:
            try:
                entry = json.loads(line)
                code = entry.get('errorCode', entry.get('code', 'unknown'))
                counts[code] = counts.get(code, 0) + 1
            except:
                pass
except FileNotFoundError:
    print("No ERROR_LOG.jsonl found")

if counts:
    print("FM code frequency (from ERROR_LOG):")
    for code, count in sorted(counts.items(), key=lambda x: -x[1])[:20]:
        print(f"  {code}: {count}")
else:
    print("No entries found")
EOF

# Get combined FM code frequency across all agents
python3 << 'EOF'
import json, glob

counts = {}
agent_counts = {}

for f in glob.glob("agents/*/ERROR_LOG.jsonl"):
    agent = f.split("/")[1]
    with open(f) as fh:
        for line in fh:
            try:
                entry = json.loads(line)
                code = entry.get('errorCode', entry.get('code', 'unknown'))
                counts[code] = counts.get(code, 0) + 1
                key = f"{agent}:{code}"
                agent_counts[key] = agent_counts.get(key, 0) + 1
            except:
                pass

print("FM code frequency (all agents):")
for code, count in sorted(counts.items(), key=lambda x: -x[1])[:20]:
    print(f"  {code}: {count}")

# Show which codes are NOT covered by existing skills
covered = {'FM-2.2', 'FM-1.1', 'FM-2.6', 'FM-3.3', 'FM-2.1', 'FM-2.3', 'FM-2.4', 'FM-5.3'}
print("\nUncovered FM codes (not targeted by existing skills):")
for code, count in sorted(counts.items(), key=lambda x: -x[1])[:20]:
    if code not in covered:
        print(f"  {code}: {count}")
EOF

