# Parse the "error" field which has the FM code
python3 << 'EOF'
import json, glob, re

counts = {}
descriptions = {}

for f in glob.glob("agents/*/ERROR_LOG.jsonl"):
    agent = f.split("/")[1]
    with open(f) as fh:
        for line in fh:
            try:
                entry = json.loads(line)
                error = entry.get('error', '')
                # Extract FM code from "FM-X.Y: DESCRIPTION"
                m = re.match(r'(FM-\d+\.\d+):\s*(.*)', error)
                if m:
                    code = m.group(1)
                    desc = m.group(2)
                    counts[code] = counts.get(code, 0) + 1
                    if code not in descriptions:
                        descriptions[code] = desc
            except:
                pass

print("FM code frequency (all agents):")
for code, count in sorted(counts.items(), key=lambda x: -x[1])[:20]:
    print(f"  {code} ({descriptions.get(code, '?')}): {count}")

covered = {'FM-2.2', 'FM-1.1', 'FM-2.6', 'FM-3.3', 'FM-2.1', 'FM-2.3', 'FM-2.4', 'FM-5.3'}
print("\nUncovered FM codes (top 10):")
for code, count in sorted(counts.items(), key=lambda x: -x[1]):
    if code not in covered:
        print(f"  {code} ({descriptions.get(code, '?')}): {count}")
EOF

